"""One-time task bootstrap. Pre-trace writes are exactly admet, task, task/raw directories.
The archive is operator-built allowlisted regular files, no links or extraction helpers.
"""
import base64,hashlib,json,os,socket,stat,subprocess,sys
from pathlib import Path
ROOT=Path('<AUTHORIZED_PROJECT_ROOT>');TASK=ROOT/'admet/hainan-skill-pilot-20261030'
assert socket.gethostname().split('.')[0]=='private-compute' and os.getuid()==1012 and os.getgid()==1012
for p in [Path('/mnt'),Path('/mnt/data'),Path('<PRIVATE_RUNTIME_PATH>'),Path('<PRIVATE_RUNTIME_PATH>'),ROOT]:
    st=p.lstat();assert stat.S_ISDIR(st.st_mode) and p.resolve()==p
mounts=[l.split()[4] for l in Path('/proc/self/mountinfo').read_text().splitlines()]
assert not any(Path(m)==ROOT or ROOT in Path(m).parents for m in mounts)
created=[]
for p in [ROOT/'admet',TASK,TASK/'raw']:
    if p==ROOT/'admet' and p.exists():assert p.resolve()==p and p.is_dir();continue
    p.mkdir();created.append(str(p))
# This exact payload program is also present locally in source/unpack_reviewed.py.
source=base64.b64decode('').decode()
env={'PATH':'/usr/bin:/bin','LANG':'C.UTF-8','HOME':str(TASK),'TMPDIR':str(TASK),'PYTHONDONTWRITEBYTECODE':'1'}
p=subprocess.run(['/usr/bin/strace','-f','-qq','-yy','-s','160','-e','trace=%file,write,writev,pwrite64,ftruncate','-o',str(TASK/'raw/upload-initial.strace'),'/usr/bin/python3','-I','-B','-c',source],stdin=sys.stdin.buffer,stdout=subprocess.PIPE,stderr=subprocess.PIPE,env=env,cwd=TASK)
print(json.dumps({'bootstrap_created':created,'upload_exit_code':p.returncode,'stdout':p.stdout.decode(),'stderr':p.stderr.decode()}));assert p.returncode==0
